var n2030_text = csvm.DomGenerator("#text", {"text":"\n  $(\".news_intro_carousel_title[index='0']\").addClass(\"show-text\")\n  $(function () {\n    updateTraffic()\n    if (localStorage.getItem(\"mainSearchTitle\")) {\n      localStorage.removeItem(\"mainSearchTitle\");\n    }\n    $(\"#searchInput\").val(\"\")\n\n    // 获取元素\n    const clickArea = $('#approval-click-area');\n    const submenu = $('#approval-submenu');\n    const container = $('.drug-registration-hover');\n\n    // 点击显示/隐藏下拉菜单\n    clickArea.on('click', function (e) {\n      e.stopPropagation(); // 阻止事件冒泡\n      submenu.toggleClass('show');\n    });\n\n    // 鼠标离开容器时隐藏菜单\n    container.on('mouseleave', function () {\n      submenu.removeClass('show');\n    });\n\n    // 点击页面其他区域隐藏菜单\n    $(document).on('click', function () {\n      submenu.removeClass('show');\n    });\n\n    // 防止下拉菜单内部点击导致菜单关闭\n    submenu.on('click', function (e) {\n      e.stopPropagation();\n    });\n  })\n\n\n"}, n2029_script);
